"""micwatch — 麦克风监控看门狗（回答"有没有空窗期不在监控输入"）

三件事：
  ① **块到达间隔**：读取线程每收到一块就 tick()。正常 = 块长（30ms）；
     间隔 > 1.6 块 = 可疑；≥ mic_gap_warn_ms（默认 250ms）= 打 WARN（含当时在忙什么）
  ② **队列深度 + 丢块**：队列 400 块(12s) 满 → 丢（qdrop，voice_agent 自己也在报）。
     这里把 qsize 一并记下来：qsize 一路涨 = 主循环被某个动作卡住
  ③ **谁在卡**：ASR / 听写 / 动作 dispatch 会 mark()，空窗告警里直接写出来

每 mic_report_s（默认 30s）打一行 INFO 小结：块数 / 平均间隔 / 最大空窗 / 丢块 / 溢出。
"""
from __future__ import annotations

import os
import threading
import time

_LOCK = threading.RLock()
_S = {
    "last": 0.0, "n": 0, "t0": 0.0, "sum_ms": 0.0, "gaps": 0, "max_gap": 0.0,
    "max_gap_at": 0.0, "ovf": 0, "max_q": 0, "last_report": 0.0, "busy": {},
    "warn_ms": 250.0, "report_s": 30.0, "block_ms": 30.0, "started": False,
}


def _log(msg, tag="SYS", level=None):
    try:
        from dlog import log
        log(msg, tag, level=level)
    except Exception:
        print(msg, flush=True)


def _knob(cfg, k, d):
    try:
        v = (cfg.behavior or {}).get(k)
        return float(v) if v is not None else float(d)
    except Exception:
        return float(d)


# ── 谁在忙 ────────────────────────────────────────────────────
def mark(name, busy=True):
    with _LOCK:
        if busy:
            _S["busy"][name] = time.time()
        else:
            _S["busy"].pop(name, None)


def busy_now():
    with _LOCK:
        return ", ".join(sorted(_S["busy"])) or "空闲"


# ── 块到达（读取线程调用）─────────────────────────────────────
def tick(qsize=0, ovf=False, blocksize_ms=None):
    now = time.time()
    bms = float(blocksize_ms or _S["block_ms"] or 30.0)
    with _LOCK:
        if _S["t0"] == 0.0:
            _S["t0"] = now
            _S["last_report"] = now
        if _S["last"] > 0:
            gap = (now - _S["last"]) * 1000.0
            _S["sum_ms"] += gap
            if gap > _S["max_gap"]:
                _S["max_gap"] = gap
                _S["max_gap_at"] = now
            # 超过 1.6 块 = 这一块之前漏了样本（设备侧或线程被抢）
            if gap > bms * 1.6:
                _S["gaps"] += 1
                if gap >= _S["warn_ms"]:
                    _log(f"   ⚠️ 麦克风空窗 {gap:.0f}ms（队列 {qsize} ｜ "
                         f"当时忙：{busy_now()}）", "WARN")
        _S["last"] = now
        _S["n"] += 1
        _S["ovf"] += 1 if ovf else 0
        if qsize > _S["max_q"]:
            _S["max_q"] = int(qsize)
    _maybe_report()


def _maybe_report(force=False):
    now = time.time()
    with _LOCK:
        if not force and (now - _S["last_report"]) < _S["report_s"]:
            return
        if _S["n"] == 0:
            return
        n = _S["n"]
        avg = (_S["sum_ms"] / max(1, n - 1)) if n > 1 else 0.0
        dur = now - _S["t0"] if _S["t0"] else 1.0
        txt = (f"🎧 麦克风监控：{dur:.0f}s 收到 {n} 块（≈{n * _S['block_ms'] / 1000:.1f}s 音频）"
               f" ｜ 平均间隔 {avg:.0f}ms ｜ 最大空窗 {_S['max_gap']:.0f}ms({_S['gaps']} 次超块)"
               f" ｜ 队列峰值 {_S['max_q']} ｜ 驱动溢出 {_S['ovf']}")
        _S["last_report"] = now
    _log(txt, "SYS", level="info")


def install(cfg=None, agent=None):
    """启动：读参数 + 起汇总线程 + 给 ASR 打"忙"标记"""
    if _S["started"]:
        return
    _S["warn_ms"] = _knob(cfg, "mic_gap_warn_ms", 250)
    _S["report_s"] = _knob(cfg, "mic_report_s", 30)
    _S["started"] = True
    _log(f"🎧 麦克风监控已启用：块 {_S['block_ms']:.0f}ms ｜ 空窗告警 ≥{_S['warn_ms']:.0f}ms ｜ "
         f"每 {_S['report_s']:.0f}s 一行小结（丢块/溢出/空窗都在这看）", "SYS", level="info")

    def _loop():
        while True:
            time.sleep(5.0)
            try:
                _maybe_report()
            except Exception:
                pass

    t = threading.Thread(target=_loop, daemon=True, name="oc-micwatch")
    t.start()

    # ASR 忙标记（不含听写/动作：那两处由 reply 的包装打标）
    try:
        asr = getattr(agent, "asr", None)
        if asr is not None and not getattr(asr.transcribe, "__oc_mw__", False):
            _orig = asr.transcribe

            def _tr(*a, **kw):
                mark("ASR")
                try:
                    return _orig(*a, **kw)
                finally:
                    mark("ASR", False)

            _tr.__oc_mw__ = True
            asr.transcribe = _tr
    except Exception:
        pass


def snapshot():
    with _LOCK:
        return dict(_S)
